def transform(grid):
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        color = row[0]
        if len(set(row)) == 1 and all(color not in other for i, other in enumerate(grid) if i != r):
            a, b = grid[:r], grid[r + 1:]
            return [[2 if x != 0 and y != 0 else 0 for x, y in zip(ra, rb)]
                    for ra, rb in zip(a, b)]
    for c in range(w):
        color = grid[0][c]
        if all(grid[r][c] == color for r in range(h)) and all(
                color not in [row[k] for k in range(w) if k != c] for row in grid):
            return [[2 if row[k] != 0 and row[c + 1 + k] != 0 else 0
                     for k in range(c)] for row in grid]
    raise ValueError("separator not found")
